{
  "components": [
    {
      "type": "claim",
      "quote": "The support group assesses the proposed corridors and recommends a planning corridor to the SFOE, together with the type of transmission technology to be used (overhead lines or underground cables).",
      "gist": "Support group evaluates corridors and recommends one to SFOE with transmission tech type."
    },
    {
      "type": "obligation",
      "quote": "the SFOE prepares a draft version of the detailed plan and initiates the consultation and participation procedure in the cantons",
      "gist": "SFOE must prepare draft plan and start cantonal consultation."
    },
    {
      "type": "obligation",
      "quote": "the SFOE then finalises the detailed plan and initiates a consultation of public authorities",
      "gist": "SFOE must finalize plan and consult public authorities."
    },
    {
      "type": "condition",
      "quote": "Within two months after the conclusion of the consultation of public authorities, the SFOE petitions the Federal Council to designate the planning corridor and applicable transmission technology",
      "gist": "SFOE petitions Federal Council within two months after public consultation ends."
    },
    {
      "type": "entity",
      "quote": "SFOE",
      "gist": "Swiss Federal Office of Energy"
    },
    {
      "type": "entity",
      "quote": "Federal Council",
      "gist": "Swiss Federal Council"
    }
  ]
}
